from questions._util import q

QUESTIONS = [
    q("k8s-pods", "medium", "A Pod is the thing you debug, but a Deployment is what you edit. Why?", "Pods are replaceable copies its ReplicaSet makes.", "Pods are read-only once the scheduler binds them.", "Edits to Pods are reverted by the kubelet on sync.", "Pods are cluster-scoped, while Deployments are not.", "The Deployment owns a ReplicaSet that owns the Pods. A replaced Pod gets a new name and IP. Treat the Pod as disposable and put the desired state in the owner."),
    q("k8s-pods", "medium", "What do two containers in one Pod share by default?", "The network namespace, so localhost works.", "The root filesystem, so files are visible.", "The process namespace, so each sees the other.", "The image layers, so writes are shared.", "localhost works. The disk does not, unless you mount the same volume. A shared PID namespace is opt-in with shareProcessNamespace."),
    q("k8s-pods", "easy", "With restartPolicy Always, what happens when the container's process exits?", "The kubelet restarts the container in the same Pod.", "The ReplicaSet replaces the Pod with a new one.", "The scheduler moves the Pod to another node.", "The Pod is marked Succeeded and left as it is.", "Restart is a kubelet action on the same Pod, which is why the restart count goes up. A controller replacing the Pod is a different event."),
    q("k8s-pods", "hard", "An init container has not finished. What is true of the app container?", "It has not started yet.", "It is running but not Ready.", "It started and is waiting on a lock.", "It is restarting in CrashLoopBackOff.", "Init containers run to completion first, in order. A stuck init container is why the app never appears. Read its logs before you blame the app image."),
    q("k8s-workloads", "medium", "You need one pod on every node, including nodes that join later. Which object?", "DaemonSet", "StatefulSet", "Deployment with anti-affinity", "ReplicaSet with a node selector", "DaemonSets track the node list. A Deployment with anti-affinity spreads a fixed replica count but will not grow with the cluster."),
    q("k8s-workloads", "medium", "A database needs a stable name and its own disk per replica. What fits?", "A StatefulSet with volumeClaimTemplates.", "A Deployment with a ReadWriteMany PVC.", "A Deployment with one PVC per replica.", "A DaemonSet with a hostPath volume.", "Ordinals and per-pod PVCs are the StatefulSet feature. A Deployment's pod names change and its replicas share one claim."),
    q("k8s-workloads", "easy", "When is a Job done?", "When enough pods exit with code 0.", "When its pods have run for activeDeadlineSeconds.", "When its pod has been scheduled once.", "When its pods pass their readiness probe.", "Jobs want completion. Deployments want a process that stays up. activeDeadlineSeconds fails a Job that runs too long."),
    q("k8s-workloads", "hard", "You changed a Deployment's pod template and the old pods are still there. What are you waiting on?", "The rollout, gated by surge settings and readiness.", "The kubelet, which applies the template on next sync.", "The old pods, which update when they next restart.", "The ReplicaSet, which needs a manual scale to apply.", "A new ReplicaSet scales up as old pods are drained, governed by maxSurge, maxUnavailable and readiness. A failing probe pins the rollout and leaves the old pods serving."),
    q("k8s-config", "medium", "You mounted a ConfigMap on /etc/app and the image's files in that directory vanished. Why?", "A volume mount hides what was in that directory.", "The kubelet empties a directory before mounting.", "ConfigMap mounts replace the image layer for it.", "The mount is read-only, so the files are hidden.", "The mount covers the directory. Image files at that path are not merged in. Mount one file with subPath, or mount on an empty path."),
    q("k8s-config", "easy", "What is a ConfigMap for?", "Non-secret configuration data.", "Credentials and API tokens.", "Node-level kubelet settings.", "Large binary files over 1MiB.", "If it is secret, use a Secret or an external store. ConfigMaps end up in manifests and logs, and they are capped at 1MiB."),
    q("k8s-config", "medium", "You edited a ConfigMap and the pod still has the old env var. Why?", "Env vars are read once, at container start.", "The kubelet syncs env vars only every 10 minutes.", "The edit needs kubectl apply, not kubectl edit.", "Env vars are cached until the node restarts.", "A mounted file can update, but env vars cannot. Roll the pod to pick up env."),
    q("k8s-config", "hard", "An immutable ConfigMap will not let you change a key. How do you ship a new revision?", "Create a new ConfigMap and point the pods at it.", "Remove immutable: true, edit the key, then re-add it.", "Use kubectl replace --force on the same name.", "Patch the key with a strategic merge patch.", "Immutability cannot be unset, and replace --force deletes and recreates it under pods using it. A new name in the pod template makes the revision explicit."),
    q("k8s-secrets", "medium", "A Kubernetes Secret is base64 in the API. What does that not give you?", "Encryption.", "Binary support.", "Namespacing.", "Projection.", "Base64 is encoding. RBAC and encryption at rest are the controls. Anyone who can get secrets can read them."),
    q("k8s-secrets", "medium", "The pod is in CreateContainerConfigError and the message names a secret. What is wrong?", "The secret or key is missing in the pod's namespace.", "The secret exists, but its data is not valid base64.", "The service account cannot read that secret.", "The secret is too large to mount as a volume.", "Config errors happen before the process starts. Read the event, which names the missing object. The kubelet fetches secrets with its own identity."),
    q("k8s-secrets", "easy", "Where should a production database password live if you can choose?", "A secret manager, injected at runtime.", "A Kubernetes Secret committed to git.", "An env value in the Deployment manifest.", "A ConfigMap in a locked-down namespace.", "Git and images leak. A cluster Secret is a step up and still needs RBAC and encryption at rest."),
    q("k8s-secrets", "hard", "You rotated a TLS secret and the ingress still serves the old cert. What is likely stale?", "The controller, or the secret name it references.", "The pods, which cached the cert at their start.", "kube-proxy, which caches TLS secrets per node.", "CoreDNS, which caches the certificate's SAN.", "Confirm the secret name on the Ingress or Gateway, then the controller's reload. Creating a second secret does nothing until it is referenced."),
    q("k8s-services", "medium", "A ClusterIP Service fronts Ready pods. What should another pod call?", "The Service's DNS name and port.", "One of the pod IPs from the endpoints.", "The node's IP on the Service's port.", "The pod's hostname from its spec.", "DNS for the Service is the API. The Service IP is stable and pod IPs change on every recreate."),
    q("k8s-services", "medium", "The Service exists and its endpoints are empty. What is the usual cause?", "Its selector matches no Ready pods.", "Its targetPort is not a named port.", "Its type is ClusterIP, not NodePort.", "kube-proxy has not synced its rules.", "kubectl get endpoints. If it is empty, either nothing matches or nothing is ready. A wrong targetPort gives endpoints that refuse connections."),
    q("k8s-services", "easy", "What is a headless Service for?", "DNS that returns pod IPs, with no VIP.", "A Service that has no selector at all.", "A ClusterIP that is reachable from outside.", "A Service with no ports, used for labels.", "clusterIP: None means the DNS name returns the pods. StatefulSets use it for stable per-pod names."),
    q("k8s-services", "hard", "A NodePort opened a port on every node. What else must allow clients to reach it?", "The cloud firewall or security group.", "A NetworkPolicy in kube-system.", "An Ingress for the Service's host.", "kube-proxy running in IPVS mode.", "Kubernetes allocating the port does not open the cloud firewall. The network in front of the node still has to allow it."),
    q("k8s-ingress", "medium", "An Ingress returns 503 and its Service has no ready endpoints. Where is the fault?", "The pods' readiness or the selector.", "The Ingress class on the resource.", "The TLS secret on the Ingress.", "The path type in the Ingress rule.", "The proxy has nobody to send to. Fix readiness and the selector first, not the Ingress rule."),
    q("k8s-ingress", "medium", "You are moving a host and two paths from an Ingress to the Gateway API. What replaces the path rules?", "An HTTPRoute attached to a Gateway.", "A GatewayClass with the path list.", "A Gateway listener per path.", "A ReferenceGrant to the Services.", "Gateway is the listener. HTTPRoute is the routing. Keep the backends pointed at the same Services until you cut traffic."),
    q("k8s-ingress", "easy", "Ingress routes HTTP. What does a Service of type LoadBalancer typically give you?", "An external address for its ports.", "Host and path routing over HTTPS.", "A DNS record in your public zone.", "TLS termination with a free cert.", "Use Ingress or Gateway when the URL matters. Use a LoadBalancer Service when you want a stable external address for a port."),
    q("k8s-ingress", "hard", "Two Ingresses claim the same host and path on one class. What happens?", "It depends on the controller's conflict rules.", "The API server rejects the second Ingress.", "The controller merges both backends evenly.", "The newer Ingress always replaces the older.", "The API server usually accepts both objects. Do not assume they merge. Read the controller's logs and docs."),
    q("k8s-probes", "medium", "A readiness exec probe always times out, though the command works by hand. Which default is too small?", "timeoutSeconds, which is 1", "periodSeconds, which is 10", "failureThreshold, which is 3", "initialDelaySeconds, which is 0", "timeoutSeconds bounds one attempt. periodSeconds is only the gap between attempts. Raise the timeout and recreate the pod."),
    q("k8s-probes", "medium", "You add only a liveness probe, and it fails when a dependency is slow. What outage did you create?", "Restarts during every slow dependency.", "Traffic sent to pods that are not ready.", "Pods stuck Pending until the check passes.", "The rollout pauses until the check passes.", "Readiness would only have removed the pod from the Service. Use liveness only for a truly stuck process, and give a slow start a startupProbe."),
    q("k8s-probes", "hard", "You fixed the probe in YAML and apply says the field is immutable. What now?", "Recreate the pod with the new spec.", "Patch the pod with --subresource=status.", "Use kubectl edit, which can change probes.", "Annotate the pod so the kubelet reloads it.", "A bare pod's probes cannot be edited. Replace the pod from the updated manifest. Through a Deployment, a template change rolls new pods."),
    q("k8s-probes", "easy", "Why does a startupProbe exist?", "To hold off liveness until a slow start finishes.", "To delay readiness by a fixed number of seconds.", "To run a command once before the app starts.", "To check that the image was pulled correctly.", "Startup runs first. Liveness and readiness take over after it succeeds. Running a command first is an init container's job."),
    q("k8s-resources", "medium", "A pod is Pending with Insufficient cpu, yet the node looks idle. Why?", "Scheduling counts requests, not usage.", "Idle CPU is reserved for system pods.", "The metrics server reports stale usage.", "CPU limits on the node are already full.", "Requests already claimed the node. Lower the request or add a node. Free cycles do not help if they are already promised, and limits do not affect scheduling."),
    q("k8s-resources", "medium", "What does Guaranteed QoS require?", "Requests equal to limits for CPU and memory.", "Requests set for CPU and memory, no limits.", "Limits set for memory, requests for CPU.", "A PriorityClass with a high value on it.", "Every container needs both, with requests equal to limits. Burstable is anything less. BestEffort is neither. Guaranteed pods are the last the OOM killer picks."),
    q("k8s-resources", "hard", "The container is throttled while the node's CPU is half idle. What did you set?", "A CPU limit below its bursts.", "A CPU request below its usage.", "A memory limit below its usage.", "A CPU request equal to its limit.", "Limits are ceilings, enforced by the cgroup even when the node has spare CPU. Requests only weight sharing. A low limit on a bursty process is a latency bug."),
    q("k8s-resources", "easy", "What does an OOMKilled status mean?", "The container passed its memory limit.", "The node ran out of disk for the container.", "The kubelet evicted the pod for pressure.", "The process hit its open-files limit.", "The cgroup hit memory.max for that container. The node may still have memory. Eviction shows as Evicted, not OOMKilled."),
    q("k8s-scheduling", "medium", "A node is tainted NoSchedule and your pod has no toleration. What happens?", "The pod is not scheduled onto that node.", "The pod is scheduled, then evicted.", "The pod is scheduled with lower priority.", "The pod waits until the taint expires.", "Tolerations let a pod through a taint. They do not prefer the node. Add affinity or a node selector for that. NoExecute is the effect that evicts."),
    q("k8s-scheduling", "medium", "You want an app's pods on different nodes. What expresses that?", "Topology spread or pod anti-affinity.", "A PodDisruptionBudget on the app.", "A node selector on the app's pods.", "A toleration on the app's pods.", "Spread is a scheduling rule. A PDB limits voluntary evictions, a selector restricts nodes, and a toleration only allows tainted ones."),
    q("k8s-scheduling", "easy", "What does nodeSelector do in the simple case?", "Restricts a pod to nodes with given labels.", "Prefers nodes with given labels, if free.", "Keeps a pod off nodes with given labels.", "Labels the node a pod is scheduled onto.", "Selector is a hard filter. Affinity adds weights and anti-affinity."),
    q("k8s-scheduling", "hard", "A pod has a toleration and a node selector that matches no node. Which explains Pending?", "The selector matches no node.", "The toleration has no matching taint.", "Both, since they must match one node.", "Neither. Pending means image pulls.", "A toleration only stops a taint excluding a node. An unused toleration is harmless. The scheduler event names the selector."),
    q("k8s-storage", "medium", "A PVC is Pending and the StorageClass exists. What else must be true for a volume to appear?", "A working provisioner that can satisfy the request.", "A pod in the same namespace running for a minute.", "A PV of the same name created by an admin.", "A ResourceQuota that allows storage requests.", "The claim is an order. A provisioner must fulfill it, or a matching PV must already exist. WaitForFirstConsumer classes also wait for a pod."),
    q("k8s-storage", "hard", "A PVC was deleted and its PV is Released, with reclaim policy Retain. How do you reuse the data?", "Clear the PV's claimRef, then bind a new claim.", "Recreate the PVC with the original name.", "Change the PV's reclaim policy to Recycle.", "Set the PV's phase back to Available.", "Retain keeps the bytes. The claimRef still points at the old claim, which is why a new claim sits Pending. Phase is status, not something you set."),
    q("k8s-storage", "medium", "A ReadWriteOnce volume is used by two pods on different nodes. What do you get?", "Only one node can attach it.", "Both pods mount it read-only.", "The second pod gets a copy.", "Both mount it, with no locking.", "RWO is per node, not per pod. Use a volume that supports the access you need, or run the pods where the disk can attach."),
    q("k8s-storage", "easy", "Where does an emptyDir live?", "On the node, for the life of the pod.", "On the node, until it is drained.", "On a PV, until the pod is deleted.", "In the container's writable layer.", "It is deleted with the pod and survives container restarts. Scratch space and caches belong there. A database does not."),
    q("k8s-rbac", "medium", "A user can list pods in one namespace and gets Forbidden in another. The role is a ClusterRole. What is missing?", "A RoleBinding in the other namespace.", "A Role copied into the other namespace.", "The aggregate-to-view label on the role.", "A ServiceAccount in the other namespace.", "A ClusterRole defines permissions. A RoleBinding grants them in one namespace. The ClusterRole existing is not a grant."),
    q("k8s-rbac", "hard", "Why is get on nodes/proxy dangerous?", "It can run commands in pods via the kubelet.", "It can read secrets mounted on the node.", "It can change the node's taints and labels.", "It can impersonate the node's identity.", "Treat nodes/proxy, pods/exec, and secrets as admin-shaped. Review bindings that grant them."),
    q("k8s-rbac", "easy", "What is a ServiceAccount?", "The identity a pod uses with the API.", "The Linux user a container runs as.", "A human user stored in the cluster.", "A Secret type for registry logins.", "It is not a human user, and it is not the process UID. Set automountServiceAccountToken: false when a workload should not talk to the API."),
    q("k8s-rbac", "medium", "Why use kubectl auth can-i?", "It evaluates all bindings for a subject.", "It lists every role bound to the subject.", "It grants a permission for one request.", "It checks the admission policies too.", "Ask what the workload can do before you ship the binding. It answers authorization, not admission."),
    q("k8s-netpol", "medium", "A namespace has no NetworkPolicies. What is the default?", "All traffic is allowed.", "All ingress is denied.", "Only same-namespace traffic.", "All egress is denied.", "The first policy that selects a pod starts the restriction for that direction. Write the allow you still need, including DNS."),
    q("k8s-netpol", "medium", "Backend ingress is locked down and you allow it from the frontend's labels. What is easy to forget?", "The frontend's egress, and DNS.", "The backend's egress to the frontend.", "A Service for the frontend pods.", "A policy in kube-system for kube-proxy.", "If egress is default-deny too, the frontend needs an allow to the backend and usually to kube-dns. Replies to an allowed connection need no rule."),
    q("k8s-netpol", "hard", "What is the least permissive policy that still lets frontend reach backend?", "Select backend, allow frontend pods on its port.", "Select backend, allow the frontend namespace.", "Select frontend, allow egress on all ports.", "Select backend, allow all pods on its port.", "Be explicit about pods, namespace and port. An empty selector matches everything."),
    q("k8s-netpol", "easy", "Who enforces NetworkPolicy?", "The CNI plugin.", "kube-proxy.", "The API server.", "The kubelet.", "If the plugin does not implement policy, the objects do nothing. Know your CNI before you trust the YAML."),
    q("k8s-psa", "medium", "A node agent DaemonSet uses hostNetwork, hostPID, and a hostPath of /proc. The namespace enforces baseline and no pods appear. Which level can run it?", "privileged", "restricted", "baseline", "host", "Those host accesses are outside baseline, and restricted is stricter still. There is no level called host. Label the namespace privileged, or exempt it on purpose."),
    q("k8s-psa", "hard", "The storefront must reject baseline violations and only warn and audit on restricted ones. Which labels?", "enforce=baseline, warn and audit=restricted", "enforce=restricted, warn and audit=baseline", "enforce=baseline, audit=restricted only", "warn=baseline, enforce and audit=restricted", "Each mode is its own label. Audit does not print. It annotates the API audit log, which is why you need warn too."),
    q("k8s-psa", "medium", "You set enforce=restricted, the running pods stay Ready, then a rollout creates nothing. Why?", "Enforce rejects only new pods.", "Enforce evicts pods on next sync.", "Enforce blocks the Deployment edit.", "Enforce waits for a namespace restart.", "Running pods are left alone. The new ones are rejected at the ReplicaSet, so check its events. Dry-run the label first, then fix the securityContext the rejection names."),
    q("k8s-psa", "easy", "Which of these does the restricted level require?", "runAsNonRoot and dropped capabilities.", "A read-only root filesystem.", "A memory limit on every container.", "An AppArmor profile on every pod.", "Restricted wants non-root, a seccomp profile, dropped capabilities, and no privilege escalation. A read-only root filesystem and limits are good practice but not part of it."),
    q("k8s-helm", "medium", "When is helm template the right command?", "To render manifests without installing.", "To upgrade a release with new values.", "To roll back a release to a revision.", "To diff the release against the cluster.", "Template is a render. Install and upgrade talk to the cluster and record a release. Diffing needs the helm-diff plugin."),
    q("k8s-helm", "medium", "The chart installs CRDs that are already in the cluster and owned elsewhere. What do you skip?", "The chart's CRDs, with --skip-crds.", "The chart's hooks, with --no-hooks.", "The namespace, with --create-namespace.", "The tests, with --skip-tests.", "Re-applying CRDs you do not own is how you fight another controller."),
    q("k8s-helm", "easy", "What is a Helm release?", "A named install of a chart with its values.", "A versioned chart tarball in a repository.", "A tagged commit of the chart's source.", "A values file for one environment.", "Upgrade changes the release. The chart is the package."),
    q("k8s-helm", "hard", "helm upgrade failed halfway and a retry is refused. What do you look at?", "helm history, for a release stuck pending.", "helm lint, for a template error in the chart.", "helm get values, for a missing required value.", "helm repo update, for a stale chart index.", "A stuck pending-upgrade blocks the next one. Read history and status, then roll back or fix the lock. Do not keep retrying blindly."),
    q("k8s-gitops", "medium", "In GitOps, what does the in-cluster controller do?", "Reconciles the cluster to what git declares.", "Pushes cluster changes back into git.", "Applies a commit once, when it is pushed.", "Deploys the newest tag in the registry.", "A kubectl edit will be reverted if git is the source of truth. Change git."),
    q("k8s-gitops", "easy", "What are Flux and Argo CD?", "GitOps controllers.", "CI pipeline runners.", "Helm chart registries.", "Service mesh proxies.", "Both reconcile manifests from a repository. The model is the same. The objects and the UI differ."),
    q("k8s-gitops", "medium", "What should a GitOps deploy of a Helm chart pin in git?", "The chart version and the values.", "The values, with the chart on latest.", "The chart repo URL and the namespace.", "The rendered manifests' resource names.", "Unpinned charts are an unreviewed upgrade. Pin both so a reconcile is repeatable."),
    q("k8s-gitops", "hard", "An image tag needs updating, and the cluster controller cannot write to git. What is a clean pattern?", "CI commits the new tag, and the controller applies it.", "CI runs kubectl set image, and the controller ignores it.", "The controller polls the registry and applies new tags.", "Developers edit the live Deployment, then sync to git.", "Git stays the source. CI proposes the tag change. The cluster does not drift ahead of git."),
    q("k8s-hpa", "medium", "A CPU HPA targets 50% and never scales. The pods have no CPU request. Why?", "Utilization is a percent of the request.", "The HPA needs a CPU limit to scale on.", "The metrics server only reports memory.", "HPA scales only when pods are throttled.", "No request means no percentage. Set the request to what the pod actually needs."),
    q("k8s-hpa", "medium", "The HPA added pods and they stayed Pending. What did you hit?", "Cluster capacity. HPA does not add nodes.", "The HPA's maxReplicas, which holds new pods.", "The metrics server lagging behind the HPA.", "A stabilization window on scale-up.", "Cluster autoscaler or a bigger pool is the next layer. HPA only changes the replica count."),
    q("k8s-hpa", "easy", "How do VPA and HPA differ?", "VPA resizes pods. HPA changes replicas.", "VPA changes replicas. HPA resizes pods.", "VPA scales nodes. HPA scales pods.", "VPA uses memory. HPA uses only CPU.", "Running both on CPU without care makes them fight. One adds pods, the other changes the request the first one measures."),
    q("k8s-hpa", "hard", "VPA should leave a pod's sidecar alone and size only the app. What is the control?", "A containerPolicy with mode Off for the sidecar.", "An updatePolicy with mode Initial for the pod.", "A separate VPA that targets only the sidecar.", "A resource limit on the sidecar so VPA skips it.", "The resource policy is per container. The app's recommendation and the sidecar's fixed size are different problems."),
    q("k8s-debug", "medium", "What does CrashLoopBackOff mean?", "The container keeps exiting and restarts are delayed.", "The image cannot be pulled and retries are delayed.", "The liveness probe passes but readiness fails.", "The node keeps rejecting the pod at admission.", "Read the previous container's logs with --previous. The current container may already be dead."),
    q("k8s-debug", "medium", "A pod from a private registry is in ImagePullBackOff. What is the first check?", "The event text: auth, missing tag, or timeout.", "The pod's ServiceAccount RBAC permissions.", "The node's disk space for the image layers.", "The pod's readiness and liveness probes.", "Unauthorized, manifest unknown, and a timeout are three different fixes: the pull secret, the image name, or the network to the registry."),
    q("k8s-debug", "hard", "kubectl exec fails because the image has no shell. What do you attach instead?", "An ephemeral container via kubectl debug.", "A sidecar added with kubectl patch.", "kubectl attach to the main container.", "kubectl port-forward and a local shell.", "Bring tools in a second container that shares the process or network namespace. Patching a pod's containers is not allowed, and attach needs a shell too."),
    q("k8s-debug", "easy", "Why is kubectl describe the first stop when a pod is not Running?", "Its events say why.", "It shows app logs.", "It retries the pod.", "It shows the YAML.", "Logs are empty if the process never started. Events still record pull, schedule, mount and probe failures."),
    q("k8s-dns", "medium", "A pod resolves internet names but not a Service name. What is the in-cluster path to check?", "CoreDNS, the search domains, and policy to it.", "The node's resolver, which serves cluster names.", "kube-proxy's DNS cache on the pod's node.", "The Ingress controller, which owns Service DNS.", "Check resolv.conf in the pod, then the CoreDNS endpoints, then NetworkPolicy. If internet names work, upstream forwarding is fine."),
    q("k8s-dns", "hard", "kubectl fails with a certificate error while workloads keep serving. What likely expired?", "The control plane's certificates.", "The pods' service account tokens.", "The cluster CA's root certificate.", "The ingress controller's TLS cert.", "The data plane keeps serving traffic it already has. kubeadm certs check-expiration, then renew, then restart the control plane static pods."),
    q("k8s-dns", "medium", "You change the cluster DNS domain from cluster.local. What has to change together?", "CoreDNS and the kubelet's clusterDomain.", "CoreDNS and every Service's spec.", "The kubelet and the API server's flags.", "CoreDNS and each pod's dnsConfig.", "Pods learn the search domain from the kubelet. Half of that change leaves resolv.conf and the server disagreeing."),
    q("k8s-dns", "easy", "How is a Service named web in namespace shop reached from another namespace?", "web.shop", "web", "shop.web", "web.svc", "The search path supplies .svc.cluster.local. A bare web only resolves in the caller's own namespace."),
]
